// Datas das viagens: ficam gravadas em português ("12 Out – 20 Out", "A partir
// de 3 Set"). Modelos só com os meses: um "{n} {x}" genérico viraria "5 Guys"
// em "Guys 5".
(function () {
  var M = { Jan: 'Jan', Fev: 'Feb', Mar: 'Mar', Abr: 'Apr', Mai: 'May', Jun: 'Jun', Jul: 'Jul', Ago: 'Aug', Set: 'Sep', Out: 'Oct', Nov: 'Nov', Dez: 'Dec' };
  var datas = [];
  Object.keys(M).forEach(function (a) {
    Object.keys(M).forEach(function (b) { datas.push(['{n} ' + a + ' – {n} ' + b, M[a] + ' {n} – ' + M[b] + ' {n}']); });
    datas.push(['A partir de {n} ' + a, 'From ' + M[a] + ' {n}']);
    datas.push(['{n} ' + a, M[a] + ' {n}']);
  });
  window.SPOT_EN_MODELOS = datas.concat(window.SPOT_EN_MODELOS);
})();
